"""Grade frozen first-pass artifacts without trusting worker build outputs."""

import hashlib
import json
import os
import re
import shutil
import signal
import subprocess
import sys
import time
from pathlib import Path

BASE = Path('/private/tmp/lazy-paired-20260910')
TS = '/tmp/lazy-appium-cli/node_modules/typescript'
ARGPARSE = Path('/tmp/lazy-appium-cli/node_modules/argparse').resolve()
GRADER_VERSION = 4
COMPILE = r'''
const fs = require('node:fs');
const ts = require(process.argv[1]);
const source = process.argv[2];
const result = ts.transpileModule(fs.readFileSync(source, 'utf8'), {
  fileName: 'candidate.ts', reportDiagnostics: true,
  compilerOptions: {module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022},
});
const errors = (result.diagnostics || []).filter(d => d.category === ts.DiagnosticCategory.Error);
console.log(JSON.stringify({typescript: ts.version, node: process.version,
  module: 'CommonJS', target: 'ES2022', typechecked: false}));
if (errors.length) {
  for (const error of errors) console.error(ts.flattenDiagnosticMessageText(error.messageText, '\n'));
  process.exit(2);
}
fs.writeFileSync(process.argv[3], result.outputText);
'''


def digest(file):
    return hashlib.sha256(file.read_bytes()).hexdigest()


def link_dependency(directory, name, source):
    directory.mkdir(parents=True, exist_ok=True)
    link = directory / name
    if link.is_symlink():
        if link.resolve() != source:
            raise RuntimeError(f'Unexpected dependency link: {link}')
    elif link.exists():
        raise RuntimeError(f'Unexpected dependency directory: {link}')
    else:
        link.symlink_to(source)


def prepare_test_root(root, frozen_tests):
    root.mkdir(parents=True, exist_ok=True)
    for name in ['.task-tests', '.task-build', 'task-tools']:
        directory = root / name
        if directory.exists():
            shutil.rmtree(directory)
        directory.mkdir()
    tests = []
    for original in frozen_tests:
        copied = root / '.task-tests' / original.name
        copied.write_bytes(original.read_bytes())
        if digest(copied) != digest(original):
            raise RuntimeError(f'Frozen test copy differs: {copied}')
        tests.append(copied)
    for directory in [root / '.task-build/node_modules', root / 'task-tools/node_modules']:
        for name, installed in [('argparse', ARGPARSE), ('typescript', Path(TS).resolve())]:
            link_dependency(directory, name, installed)
    return tests


def bounded(args, cwd, env, log, seconds=30):
    started = time.monotonic()
    with log.open('w') as output:
        process = subprocess.Popen(args, cwd=cwd, env=env, stdin=subprocess.DEVNULL,
                                   stdout=output, stderr=subprocess.STDOUT, start_new_session=True)
        timed_out = False
        try:
            process.wait(timeout=seconds)
        except subprocess.TimeoutExpired:
            timed_out = True
            try:
                os.killpg(process.pid, signal.SIGKILL)
            except ProcessLookupError:
                pass
            process.wait()
    return {'exit': 124 if timed_out else process.returncode, 'timedOut': timed_out,
            'seconds': round(time.monotonic() - started, 3), 'log': str(log)}


def tests_against(tests, module, trusted, name):
    env = os.environ.copy()
    env['CANDIDATE_MODULE'] = str(module)
    # Do not let inherited Node preload flags inject modules into adjudication.
    env.pop('NODE_OPTIONS', None)
    env.pop('NODE_PATH', None)
    return bounded(['node', '--test', '--test-timeout=10000', *map(str, tests)],
                   trusted, env, trusted / f'{name}.log')


def grade(plan, protocol, mutants):
    run = BASE / 'runs' / plan['id']
    work = Path(plan['work'])
    if not (run / 'result.json').exists():
        return False
    source = run / 'candidate-source.ts'
    frozen_tests = sorted((run / 'saved-tests').glob('*.test.cjs'))
    trusted = run / 'trusted'
    tests = prepare_test_root(trusted, frozen_tests)
    hidden = BASE / f'lazy-paired-hidden-{plan["task"]}.cjs'
    expected = protocol['frozenEvaluationSha256'][hidden.name]
    if digest(hidden) != expected:
        raise RuntimeError(f'Frozen hidden suite changed: {hidden}')
    inputs = {str(file): digest(file) for file in [source, *frozen_tests, *tests]}
    target = trusted / '.task-build/candidate.cjs'
    # Always remove an older output before compiling, including on a rerun.
    target.unlink(missing_ok=True)
    env = os.environ.copy()
    env.pop('NODE_OPTIONS', None)
    env.pop('NODE_PATH', None)
    checks = {'compile': bounded(['node', '-e', COMPILE, TS, str(source), str(target)],
                                 trusted, env, trusted / 'compile.log')}
    provenance = {'graderVersion': GRADER_VERSION, 'graderSha256': digest(Path(__file__)), 'sourceSha256': inputs[str(source)],
                  'frozenTestsSha256': {file.name: inputs[str(file)] for file in frozen_tests},
                  'executedTestsSha256': {file.name: inputs[str(file)] for file in tests},
                  'hiddenSha256': expected, 'typechecked': False,
                  'compiledSha256': digest(target) if target.exists() else None,
                  'compiledPath': str(target),
                  'argparsePath': str(ARGPARSE)}
    reference_outputs = {}
    compatibility = {'status': 'unverified', 'reasons': []}
    if not tests:
        compatibility = {'status': 'missing', 'reasons': ['No frozen saved tests.']}
    elif not any('CANDIDATE_MODULE' in file.read_text() for file in tests):
        compatibility = {'status': 'harness-incompatible',
                         'reasons': ['Saved tests do not reference the supplied CANDIDATE_MODULE contract.']}
    if checks['compile']['exit'] == 0 and target.exists():
        checks['hidden'] = tests_against([hidden], target, trusted, 'hidden')
        if tests:
            checks['candidateTests'] = tests_against(tests, target, trusted, 'candidate-tests')
            output = Path(checks['candidateTests']['log']).read_text()
            first_importer = re.search(r'Require stack:\s*\n[^\n]*?(/[^\n]+)', output)
            missing_test_import = (first_importer is not None
                                   and str(trusted / '.task-tests') in first_importer.group(1))
            if ('Cannot find module' in output or 'ERR_MODULE_NOT_FOUND' in output) and missing_test_import:
                compatibility['status'] = 'harness-incompatible'
                compatibility['reasons'].append(
                    'Frozen tests cannot resolve an import in the supplied standalone harness; inspect the log before attributing a source defect.')
            elif compatibility['status'] == 'unverified':
                compatibility['status'] = 'compatible' if checks['candidateTests']['exit'] == 0 else 'needs-review'
            checks['referenceMutations'] = {}
            references = [('baseline', Path('/tmp/lazy-paired-fixture-validation') / f'{plan["task"]}-baseline.cjs')]
            references.extend((item['name'], Path(item['file'])) for item in mutants if item['task'] == plan['task'])
            provenance['referenceModulesSha256'] = {name: digest(module) for name, module in references}
            provenance['referenceExecutedPaths'] = {}
            for name, module in references:
                reference_root = trusted / 'reference-runs' / name
                reference_tests = prepare_test_root(reference_root, frozen_tests)
                reference_target = reference_root / '.task-build/candidate.cjs'
                reference_target.write_bytes(module.read_bytes())
                expected_reference = provenance['referenceModulesSha256'][name]
                if digest(reference_target) != expected_reference:
                    raise RuntimeError(f'Reference module copy differs: {reference_target}')
                reference_outputs[str(reference_target)] = expected_reference
                inputs.update({str(file): digest(file) for file in reference_tests})
                provenance['referenceExecutedPaths'][name] = str(reference_target)
                checks['referenceMutations'][name] = tests_against(reference_tests, reference_target, reference_root, 'tests')
    inventory = bounded(['git', 'ls-files', '--others', '--exclude-standard'], work, env, trusted / 'untracked.log')
    fresh_status = bounded(['git', 'status', '--short'], work, env, trusted / 'worktree-status.log')
    tracked = bounded(['git', 'diff', '--name-only', 'HEAD'], work, env, trusted / 'tracked-changes.log')
    untracked = (trusted / 'untracked.log').read_text().splitlines() if inventory['exit'] == 0 else []
    changes = (trusted / 'tracked-changes.log').read_text().splitlines() if tracked['exit'] == 0 else []

    def allowed(name):
        return (name == plan['source'] or name.startswith(('task-tools/', '.task-build/'))
                or (name.startswith('.task-tests/') and name.endswith('.test.cjs')))

    scope = {'recordedStatusFile': str(run / 'worktree-status.txt'),
             'recordedStatus': (run / 'worktree-status.txt').read_text() if (run / 'worktree-status.txt').exists() else None,
             'freshStatus': fresh_status, 'untrackedInventory': inventory, 'trackedInventory': tracked,
             'unexpectedUntrackedForReview': [name for name in untracked if not allowed(name)],
             'unexpectedTrackedForReview': [name for name in changes if not allowed(name)],
             'scaffoldChanged': [name for name, expected_hash in plan['scaffoldHashes'].items()
                                 if not (work / name).is_file() or digest(work / name) != expected_hash],
             'workSourceMatchesFrozen': (work / plan['source']).is_file() and digest(work / plan['source']) == inputs[str(source)]}
    changed_inputs = [file for file, expected_hash in inputs.items()
                      if not Path(file).is_file() or digest(Path(file)) != expected_hash]
    changed_output = provenance['compiledSha256'] is not None and (
        not target.exists() or digest(target) != provenance['compiledSha256'])
    changed_references = [file for file, expected_hash in reference_outputs.items()
                          if not Path(file).is_file() or digest(Path(file)) != expected_hash]
    result = {'id': plan['id'], 'task': plan['task'], 'provenance': provenance, 'checks': checks,
              'savedTests': [file.name for file in tests], 'testCompatibility': compatibility, 'scope': scope,
              'frozenInputsChangedDuringGrading': changed_inputs, 'compiledOutputChangedDuringGrading': changed_output,
              'referenceOutputsChangedDuringGrading': changed_references,
              'limitations': ['Focused transpilation/runtime checks, not a full project build or typecheck.',
                              'Nonzero mutation exits require log review to separate behavioral detection from harness failure.',
                              'Unexpected scope paths require attribution/review; temporary scratch is not automatically a source defect.']}
    (run / 'trusted-grade.json').write_text(json.dumps(result, indent=2) + '\n')
    return True


if __name__ == '__main__':
    protocol = json.loads((BASE / 'protocol.json').read_text())
    mutants = json.loads((BASE / 'reference-mutants/manifest.json').read_text())
    selected = set(sys.argv[1:])
    count = 0
    for plan in protocol['runs']:
        if not selected or plan['id'] in selected:
            if grade(plan, protocol, mutants):
                count += 1
                print(f'Trusted grading written: {plan["id"]}', flush=True)
    print(f'Completed trusted grading for {count} frozen runs.', flush=True)

