const results = [];
for (const [task, name, source] of cases) {
  const compiled = ts.transpileModule(source, {reportDiagnostics: true, compilerOptions: {module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022}});
  if (compiled.diagnostics.some(d => d.category === ts.DiagnosticCategory.Error)) throw new Error(`Invalid mutant ${name}`);
  const file = path.join(out, `${task}-${name}.cjs`);
  fs.writeFileSync(file, compiled.outputText);
  require(file);
  const result = spawnSync(process.execPath, ['--test', '--test-timeout=10000', path.join(root, `lazy-paired-hidden-${task}.cjs`)], {
    env: {...process.env, CANDIDATE_MODULE: file}, encoding: 'utf8', timeout: 30000,
  });
  fs.writeFileSync(path.join(out, `${task}-${name}.log`), result.stdout + result.stderr);
  if (result.status !== 1 || !result.stdout.includes('failing tests:') || !result.stdout.includes(task === 'url' ? 'tests 3' : 'tests 7')) throw new Error(`No behavioral assertion killed ${name}: ${result.status}`);
  results.push({task, name, file, hiddenExit: result.status});
}
fs.writeFileSync(path.join(out, 'manifest.json'), JSON.stringify(results, null, 2) + '\n');
console.log(`${results.length} frozen reference mutants compile/load and fail hidden behavioral assertions.`);

