    // name list, and a backtick in the quote class cannot live in String.raw.
    name: "no-env-secret-fallback",
    pattern: new RegExp(
      "\\bprocess\\s*\\.\\s*env\\s*\\.\\s*" + CREDENTIAL_NAME_FRAGMENT + "\\s*(?:\\|\\||\\?\\?)\\s*[\"'`]",
