const fs = require('node:fs');
const path = require('node:path');
const {spawnSync} = require('node:child_process');
const ts = require('typescript');
const root = path.resolve(__dirname, '..');
const {source} = require('./task.json');
const target = path.join(root, '.task-build', 'candidate.cjs');
const output = ts.transpileModule(fs.readFileSync(path.join(root, source), 'utf8'), {
  fileName: source, reportDiagnostics: true,
  compilerOptions: {module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022},
});
const errors = (output.diagnostics || []).filter(d => d.category === ts.DiagnosticCategory.Error);
if (errors.length) {
  for (const error of errors) console.error(ts.flattenDiagnosticMessageText(error.messageText, '\n'));
  process.exit(2);
}
fs.mkdirSync(path.dirname(target), {recursive: true});
fs.writeFileSync(target, output.outputText);
if (process.argv.includes('--compile-only')) {
  console.log(target);
  process.exit(0);
}
const directory = path.join(root, '.task-tests');
const tests = fs.readdirSync(directory).filter(name => name.endsWith('.test.cjs')).sort();
if (!tests.length) {
  console.error('No saved tests. Add .task-tests/*.test.cjs using node:test.');
  process.exit(1);
}
const result = spawnSync(process.execPath,
  ['--test', '--test-timeout=10000', ...tests.map(name => path.join(directory, name))],
  {cwd: root, stdio: 'inherit', timeout: 30000,
   env: {...process.env, CANDIDATE_MODULE: target}});
if (result.error) console.error(result.error.message);
process.exit(result.status ?? 1);

